"use client";

import { forwardRef, useImperativeHandle, useCallback } from "react";
import type { AnimatedIconHandle, AnimatedIconProps } from "./types";
import { motion, useAnimate } from "motion/react";

const GithubIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  (
    { size = 24, color = "currentColor", strokeWidth = 2, className = "" },
    ref,
  ) => {
    const [scope, animate] = useAnimate();

    const start = useCallback(async () => {
      // Instantly reset paths to transparent and 0 length
      await animate(
        ".body, .tail",
        { pathLength: 0, opacity: 0 },
        { duration: 0 },
      );

      // Draw the body first
      animate(
        ".body",
        { pathLength: [0, 1], opacity: [0, 1] },
        { duration: 0.6, ease: "easeInOut" },
      );

      // Stagger the tail
      await animate(
        ".tail",
        { pathLength: [0, 1], opacity: [0, 1] },
        { duration: 0.4, ease: "easeOut", delay: 0.3 },
      );

      // Final punchy scale/rotate
      animate(
        ".github-group",
        { scale: [1, 1.1, 1], rotate: [0, -10, 10, 0] },
        { duration: 0.5, ease: "easeInOut" },
      );
    }, [animate]);

    const stop = useCallback(() => {
      animate(
        ".body, .tail",
        { pathLength: 1, opacity: 1 },
        { duration: 0.3, ease: "easeOut" },
      );
      animate(
        ".github-group",
        { scale: 1, rotate: 0 },
        { duration: 0.2, ease: "easeOut" },
      );
    }, [animate]);

    useImperativeHandle(ref, () => ({
      startAnimation: start,
      stopAnimation: stop,
    }));

    return (
      <motion.svg
        ref={scope}
        onHoverStart={start}
        onHoverEnd={stop}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`inline-flex cursor-pointer items-center justify-center ${className}`}
        style={{ overflow: "visible" }}
      >
        <motion.g
          className="github-group"
          style={{ transformOrigin: "center" }}
        >
          <path stroke="none" d="M0 0h24v24H0z" fill="none" />
          <motion.path
            className="body"
            initial={{ pathLength: 1, opacity: 1 }}
            d="M15 21v-3.5c0 -1 .1 -1.4 -.5 -2c2.8 -.3 5.5 -1.4 5.5 -6a4.6 4.6 0 0 0 -1.3 -3.2a4.2 4.2 0 0 0 -.1 -3.2s-1.1 -.3 -3.5 1.3a12.3 12.3 0 0 0 -6.2 0c-2.4 -1.6 -3.5 -1.3 -3.5 -1.3a4.2 4.2 0 0 0 -.1 3.2a4.6 4.6 0 0 0 -1.3 3.2c0 4.6 2.7 5.7 5.5 6c-.6 .6 -.6 1.2 -.5 2v3.5"
          />
          <motion.path
            className="tail"
            initial={{ pathLength: 1, opacity: 1 }}
            d="M9 19c-4.3 1.4 -4.3 -2.5 -6 -3"
          />
        </motion.g>
      </motion.svg>
    );
  },
);

GithubIcon.displayName = "GithubIcon";
export default GithubIcon;

import type { SVGMotionProps } from "motion/react";
import type { ComponentType } from "react";

export type HoverlyIconCategory = "All" | "Social" | "UI" | "Arrows";

export interface AnimatedIconHandle {
  startAnimation: () => void | Promise<void>;
  stopAnimation: () => void | Promise<void>;
}

export interface AnimatedIconProps
  extends Omit<SVGMotionProps<SVGSVGElement>, "ref"> {
  size?: number;
  color?: string;
  strokeWidth?: number;
  className?: string;
}

export type HoverlyIconProps = AnimatedIconProps;

export interface IconCliCommand {
  label: string;
  command: string;
}

export interface HoverlyIconRecord {
  slug: string;
  name: string;
  category: Exclude<HoverlyIconCategory, "All">;
  description: string;
  tags: string[];
  componentName: string;
  importPath: string;
  sourceCode: string;
  registryUrl: string;
  cliCommands: IconCliCommand[];
}

export type HoverlyIconComponent = ComponentType<AnimatedIconProps>;
